param([string]$JavaHome = 'C:\studyy\Android\Android Studio\jbr')

$ErrorActionPreference = 'Stop'
$projectRoot = [System.IO.Path]::GetFullPath((Join-Path $PSScriptRoot '..'))
$outputDirectory = Join-Path $projectRoot 'tests\build'
$javacPath = Join-Path $JavaHome 'bin\javac.exe'
$javaPath = Join-Path $JavaHome 'bin\java.exe'
if (-not (Test-Path -LiteralPath $javacPath)) { throw "JDK not found: $javacPath. Pass -JavaHome with an installed JDK." }
New-Item -ItemType Directory -Path $outputDirectory -Force | Out-Null
# Remove generated bytecode so deleted production classes cannot pass via stale output.
Get-ChildItem -LiteralPath $outputDirectory -Filter '*.class' -File -Recurse | ForEach-Object {
    Remove-Item -LiteralPath $_.FullName -Force
}
$sourcePaths = @()
$coreDirectory = Join-Path $projectRoot 'app\src\main\java\com\wangqingli\app\core'
if (Test-Path -LiteralPath $coreDirectory) {
    $sourcePaths += @(Get-ChildItem -LiteralPath $coreDirectory -Filter '*.java' -File | ForEach-Object { $_.FullName })
}
$sourcePaths += Join-Path $projectRoot 'tests\CoreTests.java'
& $javacPath --release 8 -Xlint:-options -encoding UTF-8 -d $outputDirectory @sourcePaths
if ($LASTEXITCODE -ne 0) { throw "Core compilation failed (exit $LASTEXITCODE)." }
& $javaPath -cp $outputDirectory CoreTests
if ($LASTEXITCODE -ne 0) { throw "Core tests failed (exit $LASTEXITCODE)." }
